module tb;
    reg [1023:0] in;
    reg [7:0]    sel;
    wire [3:0]   out;

    // Instantiate the DUT according to contract requirements
    TopModule dut (
        .in(in),
        .sel(sel),
        .out(out)
    );

    integer errors = 0;
    integer i;
    reg [3:0] expected;

    initial begin
        // Initialize inputs
        in = 1024'h0;
        sel = 8'h0;
        #10;

        // Test 1: Fill 'in' with a known pseudo-random or structured pattern
        // Each 4-bit chunk i will contain the value (i % 16) or similar, 
        // let's put distinct values in each 4-bit block.
        for (i = 0; i < 256; i = i + 1) begin
            in[i*4 +: 4] = i[3:0];
        end

        #10;

        // Test 2: Exhaustive or representative checks across the 256 selections
        // Checking lower boundaries, upper boundaries, and random spots to test overflow/out-of-bounds/correct slicing.
        for (i = 0; i < 256; i = i + 1) begin
            sel = i[7:0];
            #5; // propagation delay
            expected = i[3:0];

            if (out !== expected) begin
                $display("Mismatch at sel=%0d: expected %h, got %h", i, expected, out);
                errors = errors + 1;
            end
        end

        // Test 3: Check edge case where sel max out (sel = 255)
        sel = 8'hFF;
        #5;
        expected = 255[3:0];
        if (out !== expected) begin
            $display("Mismatch at max sel=255: expected %h, got %h", expected, out);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
